mapper.select:
SELECT fd.id, fd.code, fd.source_code AS sourceCode, fd.demand_type AS demandType, fd.approve_status AS approveStatus, fd.invalid_status AS invalidStatus, fd.packing_status AS packingStatus, fd.shop_id AS shopId, fd.shop_name AS shopName, fd.country_id AS countryId, fd.country_name AS countryName, fd.delivery_warehouse_id AS deliveryWarehouseId, fd.delivery_warehouse_name AS deliveryWarehouseName, fd.dest_warehouse_id AS destWarehouseId, fd.dest_warehouse_name AS destWarehouseName, fdl.logistics_method AS logisticsMethod, fdd.platform_spu_no AS platformSpuNo, fdd.platform_sku_no AS platformSkuNo, fdd.fn_sku AS fnSku, fdd.sku_id AS skuId, fdd.sku_no AS skuNo, fdd.stock_sku AS stockSku, fdd.plan_qty AS planQty, fdd.delivery_qty AS deliveryQty, fdd.is_combination AS isCombination, fd.remark AS remark, fd.create_user_name AS createUserName, fd.create_time AS createTime, fd.approve_user_name AS approveUserName, fd.approve_time AS approveTime FROM first_mile_delivery fd LEFT JOIN first_mile_delivery_logistics fdl ON fd.id = fdl.main_id AND fdl.is_deleted = FALSE LEFT JOIN first_mile_delivery_detail fdd ON fd.id = fdd.main_id AND fdd.is_deleted = FALSE WHERE fd.is_deleted = FALSE
AND fd.approve_status = #{params.tabFlag}
AND fd.code ilike concat('%',#{params.code}::text,'%')
AND fd.source_code ILIKE concat('%',#{params.sourceCode}::text,'%')
AND fd.demand_type in
#{demandType}
AND fd.shop_id in
#{shopId}
AND fd.country_id in
#{countryId}
AND fd.delivery_warehouse_id in
#{deliveryWarehouseId}
AND fd.dest_warehouse_id in
#{destWarehouseId}
AND fd.approve_status in
#{approveStatus}
AND fdl.logistics_method in
#{logisticsMethod}
and fdd.is_combination = #{params.isCombination}
AND fdd.sku_no in
#{item}
AND fdd.platform_spu_no ILIKE concat('%',#{params.platformSpuNo}::text,'%')
AND fdd.fn_sku ILIKE concat('%',#{params.fnSku}::text,'%')
AND fdd.platform_sku_no concat('%',#{params.platformSkuNo}::text,'%')
AND fd.approve_time >= #{params.approveTimeList[0]} and (#{params.approveTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > fd.approve_time
AND fd.create_time >= #{params.createTimeList[0]} and (#{params.createTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > fd.create_time
AND fd.packing_status = #{params.packingStatus}
AND EXISTS (SELECT id FROM overseas_warehouse_inbound owi WHERE owi.source_id = fd.id AND owi.is_deleted = FALSE)
AND NOT EXISTS (SELECT id FROM overseas_warehouse_inbound owi WHERE owi.source_id = fd.id AND owi.is_deleted = FALSE)
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
fd.create_time DESC, fd.code, fdd.id

SELECT fd.id, fd.code, fd.source_code, fd.demand_type, fd.approve_status, fd.invalid_status, fd.shop_id, fd.shop_name, fd.country_id, fd.country_name, fd.delivery_warehouse_id, fd.delivery_warehouse_name, fd.dest_warehouse_id, fd.dest_warehouse_name, fdl.logistics_method, fdd.platform_spu_no, fdd.platform_sku_no, fdd.fn_sku, fdd.sku_id, fdd.sku_no, fdd.stock_sku, fdd.plan_qty, fdd.delivery_qty, fd.remark, fd.create_user_name, fd.create_time, fd.approve_user_name, fd.approve_time FROM first_mile_delivery fd LEFT JOIN first_mile_delivery_logistics fdl ON fd.id = fdl.main_id AND fdl.is_deleted = FALSE LEFT JOIN first_mile_delivery_detail fdd ON fd.id = fdd.main_id AND fdd.is_deleted = FALSE WHERE fd.is_deleted = FALSE
AND fd.id IN
#{id}
AND fd.approve_status = #{params.tabFlag}
AND fd.code ILIKE concat('%',#{params.code}::text,'%')
AND fd.source_code ILIKE concat('%',#{params.sourceCode}::text,'%')
AND fd.demand_type in
#{demandType}
AND fd.shop_id in
#{shopId}
AND fd.country_id in
