SELECT fmd.id, fmd.packing_status, fmd.code, fmcb.box_no, concat(box_length, '*', fmc.box_width, '*', fmc.box_height) AS boxSize, fmc.package_weight, fmcb.box_desc FROM first_mile_delivery fmd LEFT JOIN first_mile_carton fmc ON fmc.main_id = fmd.id AND fmc.is_deleted = FALSE LEFT JOIN first_mile_carton_bill fmcb ON fmc.id = fmcb.carton_id AND fmcb.is_deleted = FALSE WHERE fmd.is_deleted = FALSE
AND fmd.id IN
#{id}
AND fmd.approve_status = #{params.tabFlag}
AND fmd.code ILIKE concat('%',#{params.code}::text,'%')
AND fmd.source_code ILIKE concat('%',#{params.sourceCode}::text,'%')
AND fmd.demand_type in
#{demandType}
AND fmd.shop_id in
#{shopId}
AND fmd.country_id in
#{countryId}
AND fmd.delivery_warehouse_id in
#{deliveryWarehouseId}
AND fmd.dest_warehouse_id in
#{destWarehouseId}
AND fmd.approve_status in
#{approveStatus}
AND fmd.approve_time >= #{params.approveTimeList[0]} and (#{params.approveTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > fmd.approve_time
AND fmd.create_time >= #{params.createTimeList[0]} and (#{params.createTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > fmd.create_time
AND fmd.delivery_status = #{params.packingStatus}
AND EXISTS (SELECT id FROM overseas_warehouse_inbound owi WHERE owi.source_id = fmd.id AND owi.is_deleted = FALSE)
AND NOT EXISTS (SELECT id FROM overseas_warehouse_inbound owi WHERE owi.source_id = fmd.id AND owi.is_deleted = FALSE)
ORDER BY fmd.code, CAST(fmcb.box_no AS INTEGER)
